gNY(){return"\u0422\u0435\u043a\u0441\u0442 \u043d\u0430\u043f\u0438\u0441\u0430\u043d \u0447\u0435\u0442\u043a\u0438\u043c, \u0441\u0440\u0435\u0434\u043d\u0438\u043c \u043f\u043e \u0440\u0430\u0437\u043c\u0435\u0440\u0443 \u043a\u0443\u0440\u0441\u0438\u0432\u043d\u044b\u043c \u043f\u043e\u0447\u0435\u0440\u043a\u043e\u043c. \u041e\u043d \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d \u0432 \u0441\u0442\u0438\u043b\u0435 scriptio continua (\u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u043e\u0435 \u043f\u0438\u0441\u044c\u043c\u043e \u0431\u0435\u0437 \u043f\u0440\u043e\u0431\u0435\u043b\u043e\u0432) \u0438 \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 nomina sacra (\u0441\u0432\u044f\u0449\u0435\u043d\u043d\u044b\u0435 \u0438\u043c\u0435\u043d\u0430) \u0432 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u043d\u043e\u0439 \u0444\u043e\u0440\u043c\u0435."},
